{
  "name": "opencode-mcp-triage",
  "version": "0.9.0",
  "description": "On-demand MCP tool activation for OpenCode — saves ~80% tokens by shrinking MCP tool descriptions and routing via keyword matching",
  "license": "MIT",
  "author": "Carlos Spagnoletti",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "mcp",
    "triage",
    "router",
    "token-optimization",
    "ai-coding-agent"
  ],
  "type": "module",
  "main": "src/index.ts",
  "exports": {
    ".": {
      "import": "./src/index.ts",
      "types": "./src/index.d.ts"
    },
    "./package.json": "./package.json"
  },
  "bin": {
    "opencode-mcp-triage": "bin/cli.js"
  },
  "files": [
    "src/",
    "bin/",
    ".opencode/commands/",
    ".opencode/plugins/",
    "postinstall.cjs",
    "README.md"
  ],
  "scripts": {
    "check": "tsc --noEmit",
    "build": "tsc -p tsconfig.cli.json",
    "test": "vitest run",
    "test:watch": "vitest",
    "postinstall": "node postinstall.cjs"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.14.0"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/plugin": {
      "optional": false
    }
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/cascharly/opencode-mcp-triage.git"
  },
  "devDependencies": {
    "@opencode-ai/plugin": ">=1.14.0",
    "@types/node": "25.7.0",
    "typescript": "6.0.3",
    "vitest": "^4.1.6"
  },
  "engines": {
    "node": ">=18"
  },
  "publishConfig": {
    "access": "public"
  },
  "directories": {
    "test": "test"
  },
  "bugs": {
    "url": "https://github.com/cascharly/opencode-mcp-triage/issues"
  },
  "homepage": "https://github.com/cascharly/opencode-mcp-triage#readme"
}
